input.schema:
{
  "type": "record",
  "name": "Appointment",
  "namespace": "axt.example.v1",
  "doc": "An appointment: an event at a time and possibly a place, such as a visit to the vet.",
  "axt.version": 1,
  "axt.title": "title",
  "fields": [
    {
      "name": "title",
      "type": "string",
      "default": "",
      "doc": "What the appointment is, as plain text on one line."
    },
    {
      "name": "start",
      "type": {
        "type": "long",
        "logicalType": "local-timestamp-millis"
      },
      "doc": "When the appointment starts, as a date and time on the wall clock; see time_zone. For an all-day appointment, 00:00 of its first day."
    },
    {
      "name": "end",
      "type": [
        "null",
        {
          "type": "long",
          "logicalType": "local-timestamp-millis"
        }
      ],
      "default": null,
      "doc": "When the appointment ends, as a date and time on the wall clock in the time zone of start; the end itself is not part of the appointment. For an all-day appointment, 00:00 of the day after its last day. Null when no end is given; an all-day appointment without an end takes one day."
    },
    {
      "name": "time_zone",
      "type": [
        "null",
        "string"
      ],
      "default": null,
      "doc": "The IANA time zone name, such as Europe/Berlin, in which start and end read on the wall clock. Null when start and end are meant in whatever time zone the user is in at that moment."
    },
    {
      "name": "all_day",
      "type": "boolean",
      "default": false,
      "doc": "True when the appointment takes whole days; the times of start and end are then 00:00 and have no meaning beyond the day."
    },
    {
      "name": "location",
      "type": "string",
      "default": "",
      "doc": "Where the appointment takes place, as text, such as an address or a room. Empty when not given."
    },
    {
      "name": "notes",
      "type": "string",
      "default": "",
      "doc": "Free notes on the appointment, as plain text; lines are separated by LF. Empty when there are none."
    },
    {
      "name": "reminders",
      "type": {
        "type": "array",
        "items": "int"
      },
      "default": [],
      "doc": "When the user wants to be reminded, each as a number of minutes before start; 0 is at start. No value is negative. Empty when there are no reminders.",
      "axt.unit": "min"
    }
  ]
}

{
  "type": "record",
  "name": "Car",
  "namespace": "axt.example.v1",
  "doc": "A car the user owns or drives.",
  "axt.version": 1,
  "axt.title": "model",
  "fields": [
    {
      "name": "make",
      "type": "string",
      "default": "",
      "doc": "The manufacturer, such as Volkswagen. Empty when not known."
    },
    {
      "name": "model",
      "type": "string",
      "default": "",
      "doc": "The model, such as Golf. Empty when not known."
    },
    {
      "name": "year",
      "type": [
        "null",
        "int"
      ],
      "default": null,
      "doc": "The model year, such as 2019. Null when not known."
    },
    {
      "name": "plate",
      "type": "string",
      "default": "",
      "doc": "The licence plate number as written on the plate. Empty when the car has none or it is not known."
    },
    {
      "name": "vin",
      "type": "string",
      "default": "",
      "doc": "The vehicle identification number of ISO 3779, 17 characters. Empty when not known."
    },
    {
      "name": "odometer",
      "type": [
        "null",
        "long"
      ],
      "default": null,
      "doc": "The distance on the odometer, in odometer_unit. Null when not known."
    },
    {
      "name": "odometer_unit",
      "type": {
        "type": "enum",
        "name": "CarDistanceUnit",
        "doc": "A unit of distance. KILOMETRE: kilometres. MILE: international miles. UNKNOWN: a unit this version does not name; a symbol this version does not know is read as UNKNOWN.",
        "symbols": [
          "KILOMETRE",
          "MILE",
          "UNKNOWN"
        ],
        "default": "UNKNOWN"
      },
      "default": "KILOMETRE",
      "doc": "The unit of odometer."
    },
    {
      "name": "notes",
      "type": "string",
      "default": "",
      "doc": "Free notes on the car, as plain text; lines are separated by LF. Empty when there are none."
    }
  ]
}

{
  "type": "record",
  "name": "Document",
  "namespace": "axt.example.v1",
  "doc": "A document: a file with a title, such as a scanned invoice, a certificate or a photo.",
  "axt.version": 1,
  "axt.title": "title",
  "fields": [
    {
      "name": "title",
      "type": "string",
      "default": "",
      "doc": "What the document is, as plain text on one line."
    },
    {
      "name": "file_name",
      "type": "string",
      "default": "",
      "doc": "The file's name with its extension, such as invoice-2026-11.pdf. Empty when not known."
    },
    {
      "name": "media_type",
      "type": "string",
      "default": "application/octet-stream",
      "doc": "The media type of content as in RFC 6838, such as application/pdf or image/jpeg."
    },
    {
      "name": "content",
      "type": "bytes",
      "default": "",
      "doc": "The file's content. The whole message, this record included, must stay within the message limit of the AXT envelope."
    },
    {
      "name": "dated",
      "type": [
        "null",
        {
          "type": "int",
          "logicalType": "date"
        }
      ],
      "default": null,
      "doc": "The date the document bears, such as the date of an invoice. Null when it bears none."
    },
    {
      "name": "notes",
      "type": "string",
      "default": "",
      "doc": "Free notes on the document, as plain text; lines are separated by LF. Empty when there are none."
    }
  ]
}

{
  "type": "record",
  "name": "Measurement",
  "namespace": "axt.example.v1",
  "doc": "One measured value or count at a point in time, such as a weight, a blood pressure reading or a tally of glasses of water.",
  "axt.version": 1,
  "axt.title": "quantity",
  "fields": [
    {
      "name": "quantity",
      "type": "string",
      "default": "",
      "doc": "What was measured or counted, as the user calls it, such as Weight or Glasses of water."
    },
    {
      "name": "value",
      "type": "double",
      "doc": "The measured value or the count, in unit."
    },
    {
      "name": "unit",
      "type": "string",
      "default": "1",
      "doc": "The unit of value as a case-sensitive code of UCUM, such as kg, Cel or mm[Hg]. A count is 1, or an annotation in braces alone that names what is counted, such as {glass}."
    },
    {
      "name": "measured_at",
      "type": {
        "type": "long",
        "logicalType": "timestamp-millis"
      },
      "doc": "When the value was measured or counted."
    },
    {
      "name": "subject",
      "type": "string",
      "default": "",
      "doc": "Who or what was measured, as text, such as the name of a pet. Empty when it is the user."
    },
    {
      "name": "notes",
      "type": "string",
      "default": "",
      "doc": "Free notes on the measurement, as plain text; lines are separated by LF. Empty when there are none."
    }
  ]
}

{
  "type": "record",
  "name": "Note",
  "namespace": "axt.example.v1",
  "doc": "A note: a piece of text the user wrote down, with a title and tags.",
  "axt.version": 1,
  "axt.title": "title",
  "fields": [
    {
      "name": "title",
      "type": "string",
      "default": "",
      "doc": "The note's title, as plain text on one line. Empty when the note has none."
    },
    {
      "name": "text",
      "type": "string",
      "default": "",
      "doc": "The note's content, written in the format named by the field format. Empty when the note has only a title."
    },
    {
      "name": "format",
      "type": {
        "type": "enum",
        "name": "NoteFormat",
        "doc": "How the text of a note is written. PLAIN: plain text, lines separated by LF. MARKDOWN: CommonMark. A symbol this version does not know is read as PLAIN.",
        "symbols": [
          "PLAIN",
          "MARKDOWN"
        ],
        "default": "PLAIN"
      },
      "default": "PLAIN",
      "doc": "How the field text is written."
    },
    {
      "name": "created",
      "type": [
        "null",
        {
          "type": "long",
          "logicalType": "timestamp-millis"
        }
      ],
      "default": null,
      "doc": "When the note was written. Null when not known."
    },
    {
      "name": "updated",
      "type": [
        "null",
        {
          "type": "long",
          "logicalType": "timestamp-millis"
        }
      ],
      "default": null,
      "doc": "When the note's content last changed. Null when not known."
    },
    {
      "name": "tags",
      "type": {
        "type": "array",
        "items": "string"
      },
      "default": [],
      "doc": "Tags the user gave the note, in the user's order and without duplicates; each a word or short phrase without a leading #. Empty when there are none."
    }
  ]
}

{
  "type": "record",
  "name": "Person",
  "namespace": "axt.example.v1",
  "doc": "A person: a contact with name, birthday, phone numbers, email addresses and postal addresses.",
  "axt.version": 1,
  "axt.title": "display_name",
  "fields": [
    {
      "name": "display_name",
      "type": "string",
      "default": "",
      "doc": "The name to show for the person, as the user wrote it, such as Dr. Anna Maria Schmidt. When empty, a receiver may build a name from the name parts."
    },
    {
      "name": "prefix",
      "type": "string",
      "default": "",
      "doc": "Titles written before the name, such as Dr. Empty when there are none."
    },
    {
      "name": "given_name",
      "type": "string",
      "default": "",
      "doc": "The given name, such as Anna. Empty when not known."
    },
    {
      "name": "middle_name",
      "type": "string",
      "default": "",
      "doc": "Further given names, such as Maria. Empty when there are none."
    },
    {
      "name": "family_name",
      "type": "string",
      "default": "",
      "doc": "The family name, such as Schmidt. Empty when not known."
    },
    {
      "name": "suffix",
      "type": "string",
      "default": "",
      "doc": "Additions written after the name, such as Jr. Empty when there are none."
    },
    {
      "name": "birthday",
      "type": [
        "null",
        {
          "type": "int",
          "logicalType": "date"
        }
      ],
      "default": null,
      "doc": "The day of birth; see birthday_year_known. Null when not known."
    },
    {
      "name": "birthday_year_known",
      "type": "boolean",
      "default": true,
      "doc": "False when only the day and month of birthday are known; the year of birthday has no meaning then, and the sender writes a leap year, such as 2000, so that 29 February can be written."
    },
    {
      "name": "phones",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "PersonPhone",
          "doc": "A phone number of a person.",
          "fields": [
            {
              "name": "label",
              "type": "string",
              "default": "",
              "doc": "What the number is for, as the user wrote it, such as home, work or mobile. Empty when not given."
            },
            {
              "name": "number",
              "type": "string",
              "default": "",
              "doc": "The phone number as written, preferably in the international format of ITU-T E.164 with a leading +, such as +49 30 1234567."
            }
          ]
        }
      },
      "default": [],
      "doc": "The person's phone numbers, in the user's order. Empty when there are none."
    },
    {
      "name": "emails",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "PersonEmail",
          "doc": "An email address of a person.",
          "fields": [
            {
              "name": "label",
              "type": "string",
              "default": "",
              "doc": "What the address is for, as the user wrote it, such as home, work or mobile. Empty when not given."
            },
            {
              "name": "address",
              "type": "string",
              "default": "",
              "doc": "The email address, such as anna@example.org."
            }
          ]
        }
      },
      "default": [],
      "doc": "The person's email addresses, in the user's order. Empty when there are none."
    },
    {
      "name": "addresses",
      "type": {
        "type": "array",
        "items": {
          "type": "record",
          "name": "PersonAddress",
          "doc": "A postal address of a person. Every part is empty when not given.",
          "fields": [
            {
              "name": "label",
              "type": "string",
              "default": "",
              "doc": "What the address is for, as the user wrote it, such as home, work or mobile. Empty when not given."
            },
            {
              "name": "street",
              "type": "string",
              "default": "",
              "doc": "The street and house number, and further lines such as a flat or a c/o, separated by LF."
            },
            {
              "name": "postal_code",
              "type": "string",
              "default": "",
              "doc": "The postal code, such as 10115."
            },
            {
              "name": "locality",
              "type": "string",
              "default": "",
              "doc": "The city, town or village."
            },
            {
              "name": "region",
              "type": "string",
              "default": "",
              "doc": "The state, province or county, where an address names one."
            },
            {
              "name": "country",
              "type": "string",
              "default": "",
              "doc": "The country, as written in the address."
            }
          ]
        }
      },
      "default": [],
      "doc": "The person's postal addresses, in the user's order. Empty when there are none."
    },
    {
      "name": "notes",
      "type": "string",
      "default": "",
      "doc": "Free notes on the person, as plain text; lines are separated by LF. Empty when there are none."
    }
  ]
}

{
  "type": "record",
  "name": "Pet",
  "namespace": "axt.example.v1",
  "doc": "A pet: an animal the user keeps, such as a cat or a dog.",
  "axt.version": 1,
  "axt.title": "name",
  "fields": [
    {
      "name": "name",
      "type": "string",
      "default": "",
      "doc": "The pet's name. Empty when it has none."
    },
    {
      "name": "species",
      "type": "string",
      "default": "",
      "doc": "The kind of animal, as the user wrote it, such as cat or dog. Empty when not given."
    },
    {
      "name": "breed",
      "type": "string",
      "default": "",
      "doc": "The breed, as the user wrote it, such as Maine Coon. Empty when not known."
    },
    {
      "name": "sex",
      "type": {
        "type": "enum",
        "name": "PetSex",
        "doc": "The sex of an animal. FEMALE, MALE: female and male. UNKNOWN: not known or not given; a symbol this version does not know is read as UNKNOWN.",
        "symbols": [
          "UNKNOWN",
          "FEMALE",
          "MALE"
        ],
        "default": "UNKNOWN"
      },
      "default": "UNKNOWN",
      "doc": "The pet's sex."
    },
    {
      "name": "neutered",
      "type": [
        "null",
        "boolean"
      ],
      "default": null,
      "doc": "True when the pet is neutered or spayed, false when it is not. Null when not known."
    },
    {
      "name": "birthday",
      "type": [
        "null",
        {
          "type": "int",
          "logicalType": "date"
        }
      ],
      "default": null,
      "doc": "The pet's day of birth. Null when not known."
    },
    {
      "name": "microchip",
      "type": "string",
      "default": "",
      "doc": "The number of the pet's microchip, as read from it; 15 digits for a chip of ISO 11784. Empty when it has none or it is not known."
    },
    {
      "name": "notes",
      "type": "string",
      "default": "",
      "doc": "Free notes on the pet, as plain text; lines are separated by LF. Empty when there are none."
    }
  ]
}

{
  "type": "record",
  "name": "Task",
  "namespace": "axt.example.v1",
  "doc": "A task: something the user wants to do, possibly by a due date, possibly repeating.",
  "axt.version": 1,
  "axt.title": "title",
  "fields": [
    {
      "name": "title",
      "type": "string",
      "default": "",
      "doc": "What is to be done, as plain text on one line."
    },
    {
      "name": "notes",
      "type": "string",
      "default": "",
      "doc": "Free notes on the task, as plain text; lines are separated by LF. Empty when there are none."
    },
    {
      "name": "due",
      "type": [
        "null",
        {
          "type": "long",
          "logicalType": "local-timestamp-millis"
        }
      ],
      "default": null,
      "doc": "The day, and the time on the wall clock, by which the task is due; see due_all_day and time_zone. Null when the task has no due date."
    },
    {
      "name": "due_all_day",
      "type": "boolean",
      "default": false,
      "doc": "True when the task is due on the day of due without a time of day; the time of due is then 00:00 and has no meaning."
    },
    {
      "name": "time_zone",
      "type": [
        "null",
        "string"
      ],
      "default": null,
      "doc": "The IANA time zone name, such as Europe/Berlin, in which due and the occurrences of repeat read on the wall clock. Null when due and the occurrences of repeat are meant in whatever time zone the user is in at that moment."
    },
    {
      "name": "repeat",
      "type": [
        "null",
        "string"
      ],
      "default": null,
      "doc": "How the task repeats: the value of an RFC 5545 RRULE property without the RRULE: prefix, such as FREQ=WEEKLY;BYDAY=TU. The occurrences start at due. Null when the task does not repeat."
    },
    {
      "name": "done",
      "type": "boolean",
      "default": false,
      "doc": "True when the task is done. For a repeating task: the occurrence at due is done."
    },
    {
      "name": "done_at",
      "type": [
        "null",
        {
          "type": "long",
          "logicalType": "timestamp-millis"
        }
      ],
      "default": null,
      "doc": "When the task was marked done. Null when it is not done or the time is not known."
    },
    {
      "name": "priority",
      "type": {
        "type": "enum",
        "name": "TaskPriority",
        "doc": "How important a task is. NONE: no priority given. LOW, MEDIUM, HIGH: low, medium and high priority. A symbol this version does not know is read as NONE.",
        "symbols": [
          "NONE",
          "LOW",
          "MEDIUM",
          "HIGH"
        ],
        "default": "NONE"
      },
      "default": "NONE",
      "doc": "How important the task is."
    }
  ]
}
